+  msg:"TLM telemetry exfil";
+  flow:established,to_server;
+  http.method; content:"POST";
+  http.uri; pcre:"/^\\/telemetry\\/v2\\/report$/";
+  http.header; content:"X-TLM-Mode|3a| exfil"; nocase;
+  http_client_body; content:"blob=";
+  http_client_body; pcre:"/blob=[A-Za-z0-9+\\/]{80,}={0,2}/";
+  http_client_body; pcre:"/sig=[0-9A-Fa-f]{64}(?:&|$)/";
+  sid:1000001;
+  rev:1;
+)
